def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C' if history[-1][1] == 'C' else 'D'

    # Gather statistics
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = 0
    my_c = 0
    cc = 0
    dd = 0
    for i in range(n):
        a = me[i]
        b = opp[i]
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'D' and b == 'D':
            dd += 1
    opp_d = n - opp_c
    last_me = me[-1]
    last_opp = opp[-1]

    # Short window analysis
    w = 10 if n >= 10 else n
    recent_opp_d = 0
    for i in range(n - w, n):
        if opp[i] == 'D':
            recent_opp_d += 1
    recent_opp_c = w - recent_opp_d

    # Endgame exploitation: if opponent is very cooperative, defect at the very end
    if n >= 96:
        if opp_c >= n - 4:
            return 'D'
        if n >= 98:
            return 'D' if opp_c > (n * 0.6) else 'C'
        return 'C'

    # Persistent defector: defend
    if recent_opp_d >= 8 and w >= 8:
        if last_opp == 'D':
            return 'D'
        # Opponent just cooperated after a bad stretch: test with C
        return 'C' if rng.random() < 0.3 else 'D'

    # Strong cooperator: preserve mutual cooperation
    if recent_opp_c >= w - 1 and w >= 5:
        # Make sure we don't get exploited too much, occasional probe
        if opp_d > 0 and rng.random() < 0.05 and n > 15:
            return 'D'
        return 'C'

    # Mostly cooperative opponent, keep cooperating
    if opp_c >= (n * 3) // 4:
        if last_opp == 'D' and last_me == 'C':
            # Single defection, retaliate once then forgive
            return 'D'
        if last_opp == 'D' and last_me == 'D':
            # Already punished, resume cooperation
            return 'C'
        return 'C'

    # Mostly defecting opponent: defect but probe occasionally
    if recent_opp_d >= (w * 7) // 10:
        if last_opp == 'C':
            return 'C' if rng.random() < 0.4 else 'D'
        return 'D'

    # Tit-for-tat with forgiveness
    if last_opp == 'D':
        if last_me == 'C':
            return 'D'
        # Both defected: try to restart cooperation occasionally
        if rng.random() < 0.25:
            return 'C'
        # Check for long mutual defection
        if n >= 6 and opp[-2] == 'D' and opp[-3] == 'D' and me[-2] == 'D':
            return 'C' if rng.random() < 0.2 else 'D'
        return 'D'

    # Opponent cooperated
    if last_me == 'D':
        # We defected and they forgave: cooperate back
        return 'C'

    # Both cooperated: maintain cooperation
    # Check for alternating retaliation pattern (CDCD...)
    if n >= 4:
        alt = 0
        for i in range(n - 4, n):
            if opp[i] == 'D' or me[i] == 'D':
                alt += 1
        if alt >= 3 and last_opp == 'C':
            # Break the cycle by cooperating
            return 'C'

    return 'C'
